-- ===== original-signal-array-reversal (EASY) =====
INSERT INTO problems (title, slug, description, difficulty, constraints_text, input_format, output_format, comparison_mode,
  float_tolerance, time_limit_seconds, memory_limit_kb, visibility, source, statement_status, execution_model, rating)
VALUES ('Array Reversal', 'original-signal-array-reversal', '## Problem

Print a list of integers in reverse order: the last element first, the first element last.

## Input

The first line contains an integer `n`. The second line contains `n` integers separated by single spaces.

## Output

Print the `n` values in reverse order on one line, separated by single spaces.

## Constraints

- `1 <= n <= 100000`
- `-1000000000 <= a[i] <= 1000000000`

## Examples

### Example 1

**Input**
```text
5
1 2 3 4 5
```
**Output**
```text
5 4 3 2 1
```
**Explanation:** The order of the five values is flipped.

### Example 2

**Input**
```text
4
-1 0 0 7
```
**Output**
```text
7 0 0 -1
```
**Explanation:** Repeated values keep their count; only the order changes.

### Example 3

**Input**
```text
1
9
```
**Output**
```text
9
```
**Explanation:** A single element is unchanged.

## Expected complexity

- Time: `O(n)`
- Auxiliary space: `O(n)`
', 'EASY', '- `1 <= n <= 100000`
- `-1000000000 <= a[i] <= 1000000000`',
  'The first line contains an integer `n`. The second line contains `n` integers separated by single spaces.', 'Print the `n` values in reverse order on one line, separated by single spaces.', 'TOKEN', NULL, 2.00, 262144, 'PUBLISHED', 'LOCAL', 'AVAILABLE', 'STDIN', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), difficulty = VALUES(difficulty),
  constraints_text = VALUES(constraints_text), input_format = VALUES(input_format), output_format = VALUES(output_format),
  comparison_mode = 'TOKEN', float_tolerance = NULL, time_limit_seconds = VALUES(time_limit_seconds),
  memory_limit_kb = VALUES(memory_limit_kb), visibility = 'PUBLISHED', statement_status = 'AVAILABLE',
  execution_model = 'STDIN', rating = NULL;
DELETE tc FROM test_cases tc JOIN problems p ON p.id = tc.problem_id WHERE p.slug = 'original-signal-array-reversal';
DELETE m FROM problem_tag_map m JOIN problems p ON p.id = m.problem_id WHERE p.slug = 'original-signal-array-reversal';
DELETE s FROM problem_starter_code s JOIN problems p ON p.id = s.problem_id WHERE p.slug = 'original-signal-array-reversal';
DELETE rs FROM reference_solutions rs JOIN problems p ON p.id = rs.problem_id WHERE p.slug = 'original-signal-array-reversal';
