-- ===== original-signal-digit-total (EASY) =====
INSERT INTO problems (title, slug, description, difficulty, constraints_text, input_format, output_format, comparison_mode,
  float_tolerance, time_limit_seconds, memory_limit_kb, visibility, source, statement_status, execution_model, rating)
VALUES ('Digit Total', 'original-signal-digit-total', '## Problem

Add up the decimal digits of a non-negative integer. For example the digits of `9990` add up to `9 + 9 + 9 + 0 = 27`.

## Input

One non-negative integer `n`, written without leading zeros.

## Output

Print the sum of the decimal digits of `n`.

## Constraints

- `0 <= n <= 10^18`

## Examples

### Example 1

**Input**
```text
12345
```
**Output**
```text
15
```
**Explanation:** 1 + 2 + 3 + 4 + 5 = 15.

### Example 2

**Input**
```text
0
```
**Output**
```text
0
```
**Explanation:** The only digit is 0.

### Example 3

**Input**
```text
9990
```
**Output**
```text
27
```
**Explanation:** 9 + 9 + 9 + 0 = 27.

## Expected complexity

- Time: `O(log n)`
- Auxiliary space: `O(1)`
', 'EASY', '- `0 <= n <= 10^18`',
  'One non-negative integer `n`, written without leading zeros.', 'Print the sum of the decimal digits of `n`.', 'TOKEN', NULL, 2.00, 262144, 'PUBLISHED', 'LOCAL', 'AVAILABLE', 'STDIN', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), difficulty = VALUES(difficulty),
  constraints_text = VALUES(constraints_text), input_format = VALUES(input_format), output_format = VALUES(output_format),
  comparison_mode = 'TOKEN', float_tolerance = NULL, time_limit_seconds = VALUES(time_limit_seconds),
  memory_limit_kb = VALUES(memory_limit_kb), visibility = 'PUBLISHED', statement_status = 'AVAILABLE',
  execution_model = 'STDIN', rating = NULL;
DELETE tc FROM test_cases tc JOIN problems p ON p.id = tc.problem_id WHERE p.slug = 'original-signal-digit-total';
DELETE m FROM problem_tag_map m JOIN problems p ON p.id = m.problem_id WHERE p.slug = 'original-signal-digit-total';
DELETE s FROM problem_starter_code s JOIN problems p ON p.id = s.problem_id WHERE p.slug = 'original-signal-digit-total';
DELETE rs FROM reference_solutions rs JOIN problems p ON p.id = rs.problem_id WHERE p.slug = 'original-signal-digit-total';
