INSERT INTO reference_solutions (problem_id, language, source_code, runtime_version, solution_version, verification_status, last_verified_at, validation_report)
SELECT p.id, 'cpp', '#include <bits/stdc++.h>
using namespace std;
int main() {
    int n; cin >> n;
    vector<long long> a(n);
    for (auto &x : a) cin >> x;
    long long k; cin >> k;
    long long ans = 0;
    if (n <= 3000) {                       // direct O(n^2) enumeration
        for (int i = 0; i < n; i++) { long long s = 0; for (int j = i; j < n; j++) { s += a[j]; if (s == k) ans++; } }
    } else {                               // prefix sums + ordered map
        map<long long, long long> seen; seen[0] = 1; long long s = 0;
        for (int i = 0; i < n; i++) { s += a[i]; auto it = seen.find(s - k); if (it != seen.end()) ans += it->second; seen[s]++; }
    }
    cout << ans << endl;
