INSERT INTO reference_solutions (problem_id, language, source_code, runtime_version, solution_version, verification_status, last_verified_at, validation_report)
SELECT p.id, 'python', 'import sys
d = sys.stdin.read().split()
n, k = int(d[0]), int(d[1])
a = [int(x) for x in d[2:2 + n]]
s = sum(a[:k])
best = s
for i in range(k, n):
    s += a[i] - a[i - k]
    best = max(best, s)
print(best)
', 'CPython 3.13.18', 1, 'VERIFIED', UTC_TIMESTAMP(6), 'Executed on 11 tests (3 public examples + 8 hidden) with CPython 3.13.18. The stored expected outputs come from this program; the independent Python and C++ references produced identical token output on every test, and every example''s stated output matched. Verified by catalog/build.py. 2 oversized hidden test(s) were executed in validation but are not stored in the migration (size cap).' FROM problems p WHERE p.slug = 'maximum-sum-subarray-of-size-k';
