INSERT INTO reference_solutions (problem_id, language, source_code, runtime_version, solution_version, verification_status, last_verified_at, validation_report)
SELECT p.id, 'python', 'import sys
d = sys.stdin.read().split()
n = int(d[0])
a = sorted(int(x) for x in d[1:1 + n])
count = 0
for i in range(n - 2):
    if i and a[i] == a[i - 1]:
        continue
    l, r = i + 1, n - 1
    while l < r:
        s = a[i] + a[l] + a[r]
        if s < 0:
            l += 1
        elif s > 0:
            r -= 1
        else:
            count += 1
            l += 1
            while l < r and a[l] == a[l - 1]:
                l += 1
print(count)
', 'CPython 3.13.18', 1, 'VERIFIED', UTC_TIMESTAMP(6), 'Executed on 12 tests (3 public examples + 9 hidden) with CPython 3.13.18. The stored expected outputs come from this program; the independent Python and C++ references produced identical token output on every test, and every example''s stated output matched. Verified by catalog/build.py.' FROM problems p WHERE p.slug = 'three-sum-distinct-triplets';
INSERT INTO reference_solutions (problem_id, language, source_code, runtime_version, solution_version, verification_status, last_verified_at, validation_report)
SELECT p.id, 'cpp', '#include <bits/stdc++.h>
using namespace std;
int main() {
    int n; cin >> n;
    vector<long long> a(n);
    for (auto &x : a) cin >> x;
    sort(a.begin(), a.end());
    if (n <= 150) {                         // brute force over all index triples, collecting distinct value triples
        set<array<long long, 3>> s;
        for (int i = 0; i < n; i++) for (int j = i + 1; j < n; j++) for (int k = j + 1; k < n; k++)
            if (a[i] + a[j] + a[k] == 0) s.insert({a[i], a[j], a[k]});
        cout << s.size() << endl;
    } else {                                // hash the pair sums of distinct values with their multiplicities
        map<long long, int> cnt; for (auto x : a) cnt[x]++;
        vector<long long> v; for (auto &p : cnt) v.push_back(p.first);
        long long total = 0;
        for (size_t i = 0; i < v.size(); i++) for (size_t j = i; j < v.size(); j++) {
            long long x = v[i], y = v[j], z = -(x + y);
            if (z < y) continue;                               // enforce x <= y <= z
            auto it = cnt.find(z); if (it == cnt.end()) continue;
            int need_x = 1 + (x == y) + (x == z), need_y = 0;  // multiplicity needed for each distinct value
            if (x == y && y == z) { if (cnt[x] >= 3) total++; }
            else if (x == y) { if (cnt[x] >= 2) total++; }
            else if (y == z) { if (cnt[y] >= 2) total++; }
            else total++;
            (void)need_x; (void)need_y;
        }
        cout << total << endl;
    }
}
', 'g++ 13.3.0 -std=c++17 -O2', 1, 'VERIFIED', UTC_TIMESTAMP(6), 'Executed on 12 tests (3 public examples + 9 hidden) with g++ 13.3.0 -std=c++17 -O2. The stored expected outputs come from this program; the independent Python and C++ references produced identical token output on every test, and every example''s stated output matched. Verified by catalog/build.py.' FROM problems p WHERE p.slug = 'three-sum-distinct-triplets';

-- ===== container-with-most-water (MEDIUM) =====
INSERT INTO problems (title, slug, description, difficulty, constraints_text, input_format, output_format, comparison_mode,
  float_tolerance, time_limit_seconds, memory_limit_kb, visibility, source, statement_status, execution_model, rating)
VALUES ('Container With Most Water', 'container-with-most-water', '## Problem

Vertical walls stand at positions `1, 2, ..., n`; wall `i` has height `h[i]`. Choose two different walls. Together with the ground they form a container whose width is the distance between the walls and whose water level is limited by the **shorter** wall:

`area = min(h[i], h[j]) * (j - i)`

Find the largest area. (Ignore the thickness of the walls.)

Start with the widest pair and move the pointer at the shorter wall inward: moving the taller wall can never help.

## Input

The first line contains `n`. The second line contains `n` wall heights.

## Output

Print the maximum area.

## Constraints

- `2 <= n <= 100000`
- `0 <= h[i] <= 10000`

## Examples

### Example 1

**Input**
```text
9
1 8 6 2 5 4 8 3 7
```
**Output**
```text
49
```
**Explanation:** Walls 2 (height 8) and 9 (height 7): width 7, level 7, area 49.

### Example 2

**Input**
```text
2
1 1
```
**Output**
```text
1
```
**Explanation:** Only one pair: `min(1,1) * 1 = 1`.

### Example 3

**Input**
```text
4
4 3 2 1
```
**Output**
```text
4
```
**Explanation:** Walls 1 and 3 (heights 4 and 2): `2 * 2 = 4`. Walls 1 and 2 give 3, walls 1 and 4 give 3.

## Expected complexity

- Time: `O(n)`
- Auxiliary space: `O(1)`
', 'MEDIUM', '- `2 <= n <= 100000`
- `0 <= h[i] <= 10000`',
  'The first line contains `n`. The second line contains `n` wall heights.', 'Print the maximum area.', 'TOKEN', NULL, 2.00, 262144, 'PUBLISHED', 'LOCAL', 'AVAILABLE', 'STDIN', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), difficulty = VALUES(difficulty),
  constraints_text = VALUES(constraints_text), input_format = VALUES(input_format), output_format = VALUES(output_format),
  comparison_mode = 'TOKEN', float_tolerance = NULL, time_limit_seconds = VALUES(time_limit_seconds),
  memory_limit_kb = VALUES(memory_limit_kb), visibility = 'PUBLISHED', statement_status = 'AVAILABLE',
  execution_model = 'STDIN', rating = NULL;
