INSERT INTO reference_solutions (problem_id, language, source_code, runtime_version, solution_version, verification_status, last_verified_at, validation_report)
SELECT p.id, 'python', 'import sys
d = sys.stdin.read().split()
n = int(d[0])
h = [int(x) for x in d[1:1 + n]]
l, r = 0, n - 1
best = 0
while l < r:
    best = max(best, min(h[l], h[r]) * (r - l))
    if h[l] < h[r]:
        l += 1
    else:
        r -= 1
print(best)
', 'CPython 3.13.18', 1, 'VERIFIED', UTC_TIMESTAMP(6), 'Executed on 10 tests (3 public examples + 7 hidden) with CPython 3.13.18. The stored expected outputs come from this program; the independent Python and C++ references produced identical token output on every test, and every example''s stated output matched. Verified by catalog/build.py. 2 oversized hidden test(s) were executed in validation but are not stored in the migration (size cap).' FROM problems p WHERE p.slug = 'container-with-most-water';
INSERT INTO reference_solutions (problem_id, language, source_code, runtime_version, solution_version, verification_status, last_verified_at, validation_report)
SELECT p.id, 'cpp', '#include <bits/stdc++.h>
using namespace std;
int main() {
    int n; cin >> n;
    vector<long long> h(n);
    for (auto &x : h) cin >> x;
    long long best = 0;
    if (n <= 3000) {                        // check every pair
        for (int i = 0; i < n; i++) for (int j = i + 1; j < n; j++) best = max(best, min(h[i], h[j]) * (j - i));
    } else {                                // for each left wall, the farthest right wall that is at least as tall
        vector<int> idx(n); iota(idx.begin(), idx.end(), 0);
        // candidate left walls: strictly increasing prefix maxima; candidate right walls: strictly increasing suffix maxima
        vector<int> L, R; long long m = -1;
        for (int i = 0; i < n; i++) if (h[i] > m) { m = h[i]; L.push_back(i); }
        m = -1;
        for (int i = n - 1; i >= 0; i--) if (h[i] > m) { m = h[i]; R.push_back(i); }
        for (int i : L) for (int j : R) if (j > i) best = max(best, min(h[i], h[j]) * (j - i));
    }
    cout << best << endl;
}
', 'g++ 13.3.0 -std=c++17 -O2', 1, 'VERIFIED', UTC_TIMESTAMP(6), 'Executed on 10 tests (3 public examples + 7 hidden) with g++ 13.3.0 -std=c++17 -O2. The stored expected outputs come from this program; the independent Python and C++ references produced identical token output on every test, and every example''s stated output matched. Verified by catalog/build.py. 2 oversized hidden test(s) were executed in validation but are not stored in the migration (size cap).' FROM problems p WHERE p.slug = 'container-with-most-water';

-- ===== first-unique-character (EASY) =====
INSERT INTO problems (title, slug, description, difficulty, constraints_text, input_format, output_format, comparison_mode,
  float_tolerance, time_limit_seconds, memory_limit_kb, visibility, source, statement_status, execution_model, rating)
VALUES ('First Unique Character', 'first-unique-character', '## Problem

Find the first character of the string that appears **exactly once** in the whole string and print its position (counting from 0). If every character repeats, print `-1`.

## Input

One line containing the string `s`.

## Output

Print the 0-based index of the first non-repeating character, or `-1`.

## Constraints

- `1 <= |s| <= 100000`
- `s` consists of lowercase English letters.

## Examples

### Example 1

**Input**
```text
leetcode
```
**Output**
```text
0
```
**Explanation:** `l` occurs once and is the first character.

### Example 2

**Input**
```text
loveleetcode
```
**Output**
```text
2
```
**Explanation:** `l` and `o` repeat; `v` at index 2 occurs once.

### Example 3

**Input**
```text
aabb
```
**Output**
```text
-1
```
**Explanation:** Both letters occur twice.

## Expected complexity

- Time: `O(n)`
- Auxiliary space: `O(alphabet size)`
', 'EASY', '- `1 <= |s| <= 100000`
- `s` consists of lowercase English letters.',
  'One line containing the string `s`.', 'Print the 0-based index of the first non-repeating character, or `-1`.', 'TOKEN', NULL, 2.00, 262144, 'PUBLISHED', 'LOCAL', 'AVAILABLE', 'STDIN', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), difficulty = VALUES(difficulty),
  constraints_text = VALUES(constraints_text), input_format = VALUES(input_format), output_format = VALUES(output_format),
  comparison_mode = 'TOKEN', float_tolerance = NULL, time_limit_seconds = VALUES(time_limit_seconds),
  memory_limit_kb = VALUES(memory_limit_kb), visibility = 'PUBLISHED', statement_status = 'AVAILABLE',
  execution_model = 'STDIN', rating = NULL;
DELETE tc FROM test_cases tc JOIN problems p ON p.id = tc.problem_id WHERE p.slug = 'first-unique-character';
DELETE m FROM problem_tag_map m JOIN problems p ON p.id = m.problem_id WHERE p.slug = 'first-unique-character';
DELETE s FROM problem_starter_code s JOIN problems p ON p.id = s.problem_id WHERE p.slug = 'first-unique-character';
DELETE rs FROM reference_solutions rs JOIN problems p ON p.id = rs.problem_id WHERE p.slug = 'first-unique-character';
INSERT INTO problem_tag_map (problem_id, tag_id)
SELECT p.id, t.id FROM problems p JOIN problem_tags t ON t.slug IN ('hashing', 'strings') WHERE p.slug = 'first-unique-character';
