INSERT INTO reference_solutions (problem_id, language, source_code, runtime_version, solution_version, verification_status, last_verified_at, validation_report)
SELECT p.id, 'python', 'import sys
d = sys.stdin.read().split()
n = int(d[0])
s = set(int(x) for x in d[1:1 + n])
best = 0
for x in s:
    if x - 1 not in s:
        y = x
        while y + 1 in s:
            y += 1
        best = max(best, y - x + 1)
print(best)
', 'CPython 3.13.18', 1, 'VERIFIED', UTC_TIMESTAMP(6), 'Executed on 12 tests (3 public examples + 9 hidden) with CPython 3.13.18. The stored expected outputs come from this program; the independent Python and C++ references produced identical token output on every test, and every example''s stated output matched. Verified by catalog/build.py. 2 oversized hidden test(s) were executed in validation but are not stored in the migration (size cap).' FROM problems p WHERE p.slug = 'longest-consecutive-sequence';
INSERT INTO reference_solutions (problem_id, language, source_code, runtime_version, solution_version, verification_status, last_verified_at, validation_report)
SELECT p.id, 'cpp', '#include <bits/stdc++.h>
using namespace std;
int main() {
    int n; cin >> n;
    vector<long long> a(n);
    for (auto &x : a) cin >> x;
    sort(a.begin(), a.end());
    a.erase(unique(a.begin(), a.end()), a.end());
    int best = 1, cur = 1;
    for (size_t i = 1; i < a.size(); i++) { if (a[i] == a[i - 1] + 1) cur++; else cur = 1; best = max(best, cur); }
    cout << best << endl;
}
', 'g++ 13.3.0 -std=c++17 -O2', 1, 'VERIFIED', UTC_TIMESTAMP(6), 'Executed on 12 tests (3 public examples + 9 hidden) with g++ 13.3.0 -std=c++17 -O2. The stored expected outputs come from this program; the independent Python and C++ references produced identical token output on every test, and every example''s stated output matched. Verified by catalog/build.py. 2 oversized hidden test(s) were executed in validation but are not stored in the migration (size cap).' FROM problems p WHERE p.slug = 'longest-consecutive-sequence';

-- ===== group-anagrams-count (MEDIUM) =====
INSERT INTO problems (title, slug, description, difficulty, constraints_text, input_format, output_format, comparison_mode,
  float_tolerance, time_limit_seconds, memory_limit_kb, visibility, source, statement_status, execution_model, rating)
VALUES ('Number of Anagram Groups', 'group-anagrams-count', '## Problem

Two words are *anagrams* if one can be rearranged into the other (they contain exactly the same letters with the same counts). Split a list of words into groups so that two words are in the same group exactly when they are anagrams. Print how many groups there are.

Identical words are anagrams of each other and fall in the same group.

## Input

The first line contains `n`. The second line contains `n` words separated by spaces.

## Output

Print the number of groups.

## Constraints

- `1 <= n <= 100000`
- Each word is a non-empty string of lowercase letters.
- The total length of all words is at most `200000`.

## Examples

### Example 1

**Input**
```text
6
eat tea tan ate nat bat
```
**Output**
```text
3
```
**Explanation:** Groups: `{eat, tea, ate}`, `{tan, nat}`, `{bat}`.

### Example 2

**Input**
```text
3
abc abc cab
```
**Output**
```text
1
```
**Explanation:** All three words use the letters a, b, c once each.

### Example 3

**Input**
```text
2
a b
```
**Output**
```text
2
```
**Explanation:** Different letters: two groups.

## Expected complexity

- Time: `O(total length)`
- Auxiliary space: `O(total length)`
', 'MEDIUM', '- `1 <= n <= 100000`
- Each word is a non-empty string of lowercase letters.
- The total length of all words is at most `200000`.',
  'The first line contains `n`. The second line contains `n` words separated by spaces.', 'Print the number of groups.', 'TOKEN', NULL, 2.00, 262144, 'PUBLISHED', 'LOCAL', 'AVAILABLE', 'STDIN', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), difficulty = VALUES(difficulty),
  constraints_text = VALUES(constraints_text), input_format = VALUES(input_format), output_format = VALUES(output_format),
  comparison_mode = 'TOKEN', float_tolerance = NULL, time_limit_seconds = VALUES(time_limit_seconds),
  memory_limit_kb = VALUES(memory_limit_kb), visibility = 'PUBLISHED', statement_status = 'AVAILABLE',
  execution_model = 'STDIN', rating = NULL;
DELETE tc FROM test_cases tc JOIN problems p ON p.id = tc.problem_id WHERE p.slug = 'group-anagrams-count';
DELETE m FROM problem_tag_map m JOIN problems p ON p.id = m.problem_id WHERE p.slug = 'group-anagrams-count';
DELETE s FROM problem_starter_code s JOIN problems p ON p.id = s.problem_id WHERE p.slug = 'group-anagrams-count';
DELETE rs FROM reference_solutions rs JOIN problems p ON p.id = rs.problem_id WHERE p.slug = 'group-anagrams-count';
INSERT INTO problem_tag_map (problem_id, tag_id)
SELECT p.id, t.id FROM problems p JOIN problem_tags t ON t.slug IN ('hashing', 'strings', 'sorting') WHERE p.slug = 'group-anagrams-count';
