SELECT p.id, 'python', 'import sys
from bisect import bisect_left, bisect_right
d = sys.stdin.read().split()
n, x = int(d[0]), int(d[1])
a = [int(v) for v in d[2:2 + n]]
l = bisect_left(a, x)
if l == n or a[l] != x:
    print(''-1 -1'')
else:
    print(l, bisect_right(a, x) - 1)
