INSERT INTO reference_solutions (problem_id, language, source_code, runtime_version, solution_version, verification_status, last_verified_at, validation_report)
SELECT p.id, 'python', 'import sys
d = sys.stdin.read().split()
n, D = int(d[0]), int(d[1])
w = [int(x) for x in d[2:2 + n]]

def days(c):
    cnt, cur = 1, 0
    for x in w:
        if cur + x > c:
            cnt += 1
            cur = 0
        cur += x
    return cnt

lo, hi = max(w), sum(w)
while lo < hi:
    mid = (lo + hi) // 2
    if days(mid) <= D:
        hi = mid
    else:
        lo = mid + 1
print(lo)
', 'CPython 3.13.18', 1, 'VERIFIED', UTC_TIMESTAMP(6), 'Executed on 12 tests (3 public examples + 9 hidden) with CPython 3.13.18. The stored expected outputs come from this program; the independent Python and C++ references produced identical token output on every test, and every example''s stated output matched. Verified by catalog/build.py.' FROM problems p WHERE p.slug = 'minimum-shipping-capacity';
INSERT INTO reference_solutions (problem_id, language, source_code, runtime_version, solution_version, verification_status, last_verified_at, validation_report)
SELECT p.id, 'cpp', '#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, D; cin >> n >> D;
    vector<int> w(n);
    for (auto &x : w) cin >> x;
    long long sum = accumulate(w.begin(), w.end(), 0LL);
    int mx = *max_element(w.begin(), w.end());
    auto need = [&](long long c) { int d = 1; long long cur = 0; for (int x : w) { if (cur + x > c) { d++; cur = 0; } cur += x; } return d; };
    if (sum <= 200000) {                    // linear scan over capacities
        for (long long c = mx; c <= sum; c++) if (need(c) <= D) { cout << c << endl; return 0; }
    }
    long long lo = mx, hi = sum;            // otherwise binary search
    while (lo < hi) { long long mid = (lo + hi) / 2; if (need(mid) <= D) hi = mid; else lo = mid + 1; }
    cout << lo << endl;
}
', 'g++ 13.3.0 -std=c++17 -O2', 1, 'VERIFIED', UTC_TIMESTAMP(6), 'Executed on 12 tests (3 public examples + 9 hidden) with g++ 13.3.0 -std=c++17 -O2. The stored expected outputs come from this program; the independent Python and C++ references produced identical token output on every test, and every example''s stated output matched. Verified by catalog/build.py.' FROM problems p WHERE p.slug = 'minimum-shipping-capacity';

