using namespace std;
int main() {
    int n; cin >> n;
    vector<string> v(n); for (auto &x : v) cin >> x;
    int k; cin >> k;
    // Real linked list with a dummy head and two pointers.
    vector<int> nxt(n + 1); for (int i = 0; i <= n; i++) nxt[i] = (i < n) ? i + 1 : -1;   // node i+1 stores v[i]; node 0 is the dummy
