    while (nx[fast] != -1) { fast = nx[fast]; slow = nx[slow]; }
    nx[slow] = nx[nx[slow]];
    string out; int cur = nx[0], cnt = 0;
    while (cur != -1) { if (cnt++) out += '' ''; out += v[cur - 1]; cur = nx[cur]; }
    cout << (cnt ? out : string("empty")) << endl;
}
