INSERT INTO reference_solutions (problem_id, language, source_code, runtime_version, solution_version, verification_status, last_verified_at, validation_report)
SELECT p.id, 'python', 'import sys
from collections import deque
d = sys.stdin.read().split()
n, k = int(d[0]), int(d[1])
a = [int(x) for x in d[2:2 + n]]
dq = deque()
out = []
for i, x in enumerate(a):
    while dq and a[dq[-1]] <= x:
        dq.pop()
    dq.append(i)
    if dq[0] <= i - k:
        dq.popleft()
    if i >= k - 1:
        out.append(a[dq[0]])
print('' ''.join(map(str, out)))
', 'CPython 3.13.18', 1, 'VERIFIED', UTC_TIMESTAMP(6), 'Executed on 11 tests (2 public examples + 9 hidden) with CPython 3.13.18. The stored expected outputs come from this program; the independent Python and C++ references produced identical token output on every test, and every example''s stated output matched. Verified by catalog/build.py. 3 oversized hidden test(s) were executed in validation but are not stored in the migration (size cap).' FROM problems p WHERE p.slug = 'sliding-window-maximum';
INSERT INTO reference_solutions (problem_id, language, source_code, runtime_version, solution_version, verification_status, last_verified_at, validation_report)
SELECT p.id, 'cpp', '#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, k; scanf("%d %d", &n, &k);
    vector<long long> a(n);
    for (auto &x : a) scanf("%lld", &x);
    multiset<long long> w;                  // ordered multiset of the current window
    vector<long long> out;
    for (int i = 0; i < n; i++) {
        w.insert(a[i]);
        if (i >= k) w.erase(w.find(a[i - k]));
        if (i >= k - 1) out.push_back(*w.rbegin());
    }
    for (size_t i = 0; i < out.size(); i++) printf("%lld%c", out[i], i + 1 < out.size() ? '' '' : ''\\n'');
}
', 'g++ 13.3.0 -std=c++17 -O2', 1, 'VERIFIED', UTC_TIMESTAMP(6), 'Executed on 11 tests (2 public examples + 9 hidden) with g++ 13.3.0 -std=c++17 -O2. The stored expected outputs come from this program; the independent Python and C++ references produced identical token output on every test, and every example''s stated output matched. Verified by catalog/build.py. 3 oversized hidden test(s) were executed in validation but are not stored in the migration (size cap).' FROM problems p WHERE p.slug = 'sliding-window-maximum';

-- ===== generate-parentheses (MEDIUM) =====
INSERT INTO problems (title, slug, description, difficulty, constraints_text, input_format, output_format, comparison_mode,
  float_tolerance, time_limit_seconds, memory_limit_kb, visibility, source, statement_status, execution_model, rating)
VALUES ('Generate Balanced Parentheses', 'generate-parentheses', '## Problem

Print every balanced string made of exactly `n` pairs of round brackets `(` and `)`. A string is balanced if, reading left to right, the number of `)` never exceeds the number of `(` and the totals are equal at the end.

Print the strings in **lexicographic order** where `(` comes before `)`, one per line. Backtracking works well: add `(` while fewer than `n` have been used, and add `)` only while it keeps the prefix valid.

## Input

One integer `n`.

## Output

Print each balanced string on its own line, in lexicographic order.

## Constraints

- `1 <= n <= 8`

## Examples

### Example 1

**Input**
```text
1
```
**Output**
```text
()
```
**Explanation:** There is exactly one balanced string with one pair.

### Example 2

**Input**
```text
3
```
**Output**
```text
((()))
(()())
(())()
()(())
()()()
```
**Explanation:** The five balanced strings for `n = 3`, in lexicographic order.

## Expected complexity

- Time: `O(4^n / sqrt(n))`
- Auxiliary space: `O(n) recursion depth`
', 'MEDIUM', '- `1 <= n <= 8`',
  'One integer `n`.', 'Print each balanced string on its own line, in lexicographic order.', 'TOKEN', NULL, 2.00, 262144, 'PUBLISHED', 'LOCAL', 'AVAILABLE', 'STDIN', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), difficulty = VALUES(difficulty),
  constraints_text = VALUES(constraints_text), input_format = VALUES(input_format), output_format = VALUES(output_format),
  comparison_mode = 'TOKEN', float_tolerance = NULL, time_limit_seconds = VALUES(time_limit_seconds),
  memory_limit_kb = VALUES(memory_limit_kb), visibility = 'PUBLISHED', statement_status = 'AVAILABLE',
  execution_model = 'STDIN', rating = NULL;
DELETE tc FROM test_cases tc JOIN problems p ON p.id = tc.problem_id WHERE p.slug = 'generate-parentheses';
DELETE m FROM problem_tag_map m JOIN problems p ON p.id = m.problem_id WHERE p.slug = 'generate-parentheses';
DELETE s FROM problem_starter_code s JOIN problems p ON p.id = s.problem_id WHERE p.slug = 'generate-parentheses';
DELETE rs FROM reference_solutions rs JOIN problems p ON p.id = rs.problem_id WHERE p.slug = 'generate-parentheses';
