SELECT p.id, 'python', 'n = int(input())
out = []

def go(s, o, c):
    if len(s) == 2 * n:
        out.append(s)
        return
    if o < n:
        go(s + ''('', o + 1, c)
    if c < o:
        go(s + '')'', o, c + 1)

go('''', 0, 0)
print(''\\n''.join(out))
', 'CPython 3.13.18', 1, 'VERIFIED', UTC_TIMESTAMP(6), 'Executed on 8 tests (2 public examples + 6 hidden) with CPython 3.13.18. The stored expected outputs come from this program; the independent Python and C++ references produced identical token output on every test, and every example''s stated output matched. Verified by catalog/build.py.' FROM problems p WHERE p.slug = 'generate-parentheses';
INSERT INTO reference_solutions (problem_id, language, source_code, runtime_version, solution_version, verification_status, last_verified_at, validation_report)
SELECT p.id, 'cpp', '#include <bits/stdc++.h>
using namespace std;
int main() {
    int n; cin >> n; int L = 2 * n;
    // Enumerate every bit pattern in increasing order (0 = ''('' < 1 = '')'') and keep the balanced ones.
    for (long long mask = 0; mask < (1LL << L); mask++) {
        int bal = 0; bool good = true; string s;
        for (int i = L - 1; i >= 0; i--) {
            int bit = (mask >> i) & 1;
            bal += bit ? -1 : 1; s += bit ? '')'' : ''('';
            if (bal < 0) { good = false; break; }
        }
        if (good && bal == 0) cout << s << "\\n";
    }
}
', 'g++ 13.3.0 -std=c++17 -O2', 1, 'VERIFIED', UTC_TIMESTAMP(6), 'Executed on 8 tests (2 public examples + 6 hidden) with g++ 13.3.0 -std=c++17 -O2. The stored expected outputs come from this program; the independent Python and C++ references produced identical token output on every test, and every example''s stated output matched. Verified by catalog/build.py.' FROM problems p WHERE p.slug = 'generate-parentheses';

-- ===== count-subsets-with-sum (MEDIUM) =====
INSERT INTO problems (title, slug, description, difficulty, constraints_text, input_format, output_format, comparison_mode,
  float_tolerance, time_limit_seconds, memory_limit_kb, visibility, source, statement_status, execution_model, rating)
VALUES ('Count Subsets With a Given Sum', 'count-subsets-with-sum', '## Problem

Count the subsets of the array (choosing any set of **positions**) whose elements add up to exactly `K`. Equal values at different positions are different elements, so they give different subsets. The empty subset is never counted because `K >= 1`.

With at most 20 elements you may try both choices (take or skip) for every element.

## Input

The first line contains `n` and `K`. The second line contains `n` positive integers.

## Output

Print the number of subsets with sum `K`.

## Constraints

- `1 <= n <= 20`
- `1 <= a[i] <= 50`
- `1 <= K <= 1000`

## Examples

### Example 1

**Input**
```text
4 5
1 2 3 4
```
**Output**
```text
2
```
**Explanation:** `{2, 3}` and `{1, 4}` both sum to 5.

### Example 2

**Input**
```text
3 2
1 1 1
```
**Output**
```text
3
```
**Explanation:** Any two of the three equal elements: three different position pairs.

### Example 3

**Input**
```text
2 10
3 4
```
**Output**
```text
0
```
**Explanation:** The total is 7, so 10 is unreachable.

## Expected complexity

- Time: `O(n * K) with DP (2^n by plain backtracking)`
- Auxiliary space: `O(K)`
', 'MEDIUM', '- `1 <= n <= 20`
- `1 <= a[i] <= 50`
- `1 <= K <= 1000`',
  'The first line contains `n` and `K`. The second line contains `n` positive integers.', 'Print the number of subsets with sum `K`.', 'TOKEN', NULL, 2.00, 262144, 'PUBLISHED', 'LOCAL', 'AVAILABLE', 'STDIN', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), difficulty = VALUES(difficulty),
  constraints_text = VALUES(constraints_text), input_format = VALUES(input_format), output_format = VALUES(output_format),
  comparison_mode = 'TOKEN', float_tolerance = NULL, time_limit_seconds = VALUES(time_limit_seconds),
  memory_limit_kb = VALUES(memory_limit_kb), visibility = 'PUBLISHED', statement_status = 'AVAILABLE',
  execution_model = 'STDIN', rating = NULL;
