DELETE m FROM problem_tag_map m JOIN problems p ON p.id = m.problem_id WHERE p.slug = 'count-subsets-with-sum';
DELETE s FROM problem_starter_code s JOIN problems p ON p.id = s.problem_id WHERE p.slug = 'count-subsets-with-sum';
DELETE rs FROM reference_solutions rs JOIN problems p ON p.id = rs.problem_id WHERE p.slug = 'count-subsets-with-sum';
