SELECT p.id, 'cpp', '#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, K; cin >> n >> K;
    vector<int> a(n); for (auto &x : a) cin >> x;
    vector<long long> dp(K + 1, 0); dp[0] = 1;       // dp[s] = number of subsets so far with sum s
    for (int x : a) for (int s = K; s >= x; s--) dp[s] += dp[s - x];
    cout << dp[K] << endl;
}
