SELECT p.id, 'python', 'import sys
d = sys.stdin.read().split()
n = int(d[0])
V = [0] * (n + 1); L = [0] * (n + 1); R = [0] * (n + 1)
for i in range(1, n + 1):
    V[i] = int(d[3 * i - 2]); L[i] = int(d[3 * i - 1]); R[i] = int(d[3 * i])
INF = 10 ** 18
st = [(1, -INF, INF)]
res = True
while st and res:
    u, lo, hi = st.pop()
    if not (lo < V[u] < hi):
        res = False
        break
    if L[u]:
        st.append((L[u], lo, V[u]))
    if R[u]:
        st.append((R[u], V[u], hi))
print(''true'' if res else ''false'')
', 'CPython 3.13.18', 1, 'VERIFIED', UTC_TIMESTAMP(6), 'Executed on 14 tests (4 public examples + 10 hidden) with CPython 3.13.18. The stored expected outputs come from this program; the independent Python and C++ references produced identical token output on every test, and every example''s stated output matched. Verified by catalog/build.py. 4 oversized hidden test(s) were executed in validation but are not stored in the migration (size cap).' FROM problems p WHERE p.slug = 'validate-binary-search-tree';
INSERT INTO reference_solutions (problem_id, language, source_code, runtime_version, solution_version, verification_status, last_verified_at, validation_report)
SELECT p.id, 'cpp', '#include <bits/stdc++.h>
using namespace std;
int main() {
    int n; scanf("%d", &n);
    vector<long long> V(n + 1); vector<int> L(n + 1), R(n + 1);
    for (int i = 1; i <= n; i++) scanf("%lld %d %d", &V[i], &L[i], &R[i]);
    // In-order traversal (iterative); a BST visits values in strictly increasing order.
    vector<int> st; int cur = 1; long long prev = LLONG_MIN; bool good = true;
    while ((cur || !st.empty()) && good) {
        while (cur) { st.push_back(cur); cur = L[cur]; }
        cur = st.back(); st.pop_back();
        if (V[cur] <= prev) good = false;
        prev = V[cur];
        cur = R[cur];
    }
    puts(good ? "true" : "false");
}
', 'g++ 13.3.0 -std=c++17 -O2', 1, 'VERIFIED', UTC_TIMESTAMP(6), 'Executed on 14 tests (4 public examples + 10 hidden) with g++ 13.3.0 -std=c++17 -O2. The stored expected outputs come from this program; the independent Python and C++ references produced identical token output on every test, and every example''s stated output matched. Verified by catalog/build.py. 4 oversized hidden test(s) were executed in validation but are not stored in the migration (size cap).' FROM problems p WHERE p.slug = 'validate-binary-search-tree';

-- ===== kth-largest-element (MEDIUM) =====
INSERT INTO problems (title, slug, description, difficulty, constraints_text, input_format, output_format, comparison_mode,
  float_tolerance, time_limit_seconds, memory_limit_kb, visibility, source, statement_status, execution_model, rating)
VALUES ('K-th Largest Element', 'kth-largest-element', '## Problem

Find the `k`-th largest element of an unsorted array. Duplicates count separately: in `5 5 3` the 1st and 2nd largest are both 5 and the 3rd largest is 3.

Sorting works, but a *min-heap* that never holds more than `k` elements finds the answer in `O(n log k)`.

## Input

The first line contains `n` and `k`. The second line contains `n` integers.

## Output

Print the `k`-th largest element.

## Constraints

- `1 <= k <= n <= 100000`
- `-1000000000 <= a[i] <= 1000000000`

## Examples

### Example 1

**Input**
```text
6 2
3 2 1 5 6 4
```
**Output**
```text
5
```
**Explanation:** Sorted descending: 6 5 4 3 2 1. The 2nd is 5.

### Example 2

**Input**
```text
9 4
3 2 3 1 2 4 5 5 6
```
**Output**
```text
4
```
**Explanation:** Sorted descending: 6 5 5 4 3 3 2 2 1; the 4th is 4 (duplicates count).

### Example 3

**Input**
```text
1 1
-7
```
**Output**
```text
-7
```
**Explanation:** A single element.

## Expected complexity

- Time: `O(n log k)`
- Auxiliary space: `O(k)`
', 'MEDIUM', '- `1 <= k <= n <= 100000`
- `-1000000000 <= a[i] <= 1000000000`',
  'The first line contains `n` and `k`. The second line contains `n` integers.', 'Print the `k`-th largest element.', 'TOKEN', NULL, 2.00, 262144, 'PUBLISHED', 'LOCAL', 'AVAILABLE', 'STDIN', NULL)
ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), difficulty = VALUES(difficulty),
  constraints_text = VALUES(constraints_text), input_format = VALUES(input_format), output_format = VALUES(output_format),
  comparison_mode = 'TOKEN', float_tolerance = NULL, time_limit_seconds = VALUES(time_limit_seconds),
  memory_limit_kb = VALUES(memory_limit_kb), visibility = 'PUBLISHED', statement_status = 'AVAILABLE',
  execution_model = 'STDIN', rating = NULL;
DELETE tc FROM test_cases tc JOIN problems p ON p.id = tc.problem_id WHERE p.slug = 'kth-largest-element';
