SELECT p.id, 'python', 'import sys
d = sys.stdin.read().split()
r, c = int(d[0]), int(d[1])
g = [bytearray(row.encode()) for row in d[2:2 + r]]
cnt = 0
for i in range(r):
    for j in range(c):
        if g[i][j] == 49:
            cnt += 1
            g[i][j] = 48
            st = [(i, j)]
            while st:
                x, y = st.pop()
                for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                    if 0 <= nx < r and 0 <= ny < c and g[nx][ny] == 49:
                        g[nx][ny] = 48
                        st.append((nx, ny))
print(cnt)
