SELECT p.id, 'python', 'import sys
from collections import deque
d = sys.stdin.buffer.read().split()
n, m, s, t = int(d[0]), int(d[1]), int(d[2]), int(d[3])
adj = [[] for _ in range(n + 1)]
for i in range(m):
    u = int(d[4 + 2 * i]); v = int(d[5 + 2 * i])
    adj[u].append(v)
    adj[v].append(u)
dist = [-1] * (n + 1)
dist[s] = 0
q = deque([s])
while q:
    u = q.popleft()
    for v in adj[u]:
        if dist[v] < 0:
            dist[v] = dist[u] + 1
            q.append(v)
print(dist[t])
