SELECT p.id, 'python', 'import sys
from collections import deque
d = sys.stdin.buffer.read().split()
n, m = int(d[0]), int(d[1])
adj = [[] for _ in range(n + 1)]
indeg = [0] * (n + 1)
for i in range(m):
    a = int(d[2 + 2 * i]); b = int(d[3 + 2 * i])
    adj[a].append(b)
    indeg[b] += 1
q = deque(i for i in range(1, n + 1) if indeg[i] == 0)
done = 0
while q:
    u = q.popleft()
    done += 1
    for v in adj[u]:
        indeg[v] -= 1
        if indeg[v] == 0:
            q.append(v)
print(''true'' if done == n else ''false'')
', 'CPython 3.13.18', 1, 'VERIFIED', UTC_TIMESTAMP(6), 'Executed on 13 tests (3 public examples + 10 hidden) with CPython 3.13.18. The stored expected outputs come from this program; the independent Python and C++ references produced identical token output on every test, and every example''s stated output matched. Verified by catalog/build.py. 4 oversized hidden test(s) were executed in validation but are not stored in the migration (size cap).' FROM problems p WHERE p.slug = 'course-schedule-possible';
INSERT INTO reference_solutions (problem_id, language, source_code, runtime_version, solution_version, verification_status, last_verified_at, validation_report)
SELECT p.id, 'cpp', '#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, m; scanf("%d %d", &n, &m);
    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < m; i++) { int a, b; scanf("%d %d", &a, &b); adj[a].push_back(b); }
    // Iterative depth-first search with three colours: finding a grey node again means a cycle.
    vector<int> color(n + 1, 0), it(n + 1, 0);
    bool cyc = false;
    for (int s = 1; s <= n && !cyc; s++) {
        if (color[s]) continue;
        vector<int> st{s}; color[s] = 1;
        while (!st.empty() && !cyc) {
            int u = st.back();
            if (it[u] < (int)adj[u].size()) {
                int v = adj[u][it[u]++];
                if (color[v] == 1) cyc = true;
                else if (color[v] == 0) { color[v] = 1; st.push_back(v); }
            } else { color[u] = 2; st.pop_back(); }
        }
    }
    puts(cyc ? "false" : "true");
}
