d = sys.stdin.read().split()
n, amt = int(d[0]), int(d[1])
coins = [int(x) for x in d[2:2 + n]]
INF = 10 ** 9
best = [0] + [INF] * amt
for x in range(1, amt + 1):
    for c in coins:
        if c <= x and best[x - c] + 1 < best[x]:
