using namespace std;
int main() {
    string s, t; cin >> s >> t;
    int n = s.size(), m = t.size();
    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));     // full table
    for (int i = n - 1; i >= 0; i--) for (int j = m - 1; j >= 0; j--)     // suffix formulation
        dp[i][j] = (s[i] == t[j]) ? dp[i + 1][j + 1] + 1 : max(dp[i + 1][j], dp[i][j + 1]);
    cout << dp[0][0] << endl;
}
