SELECT p.id, 'cpp', '#include <bits/stdc++.h>
using namespace std;
int main() {
    int n; cin >> n;
    if (n <= 200000) {                              // trial division
        int cnt = 0;
        for (int x = 2; x <= n; x++) { bool pr = true; for (int d = 2; (long long)d * d <= x; d++) if (x % d == 0) { pr = false; break; } cnt += pr; }
        cout << cnt << endl;
    } else {                                        // linear sieve: every composite is removed once by its smallest prime
        vector<int> primes; vector<char> comp(n + 1, 0);
        for (int i = 2; i <= n; i++) {
            if (!comp[i]) primes.push_back(i);
            for (int p : primes) { if ((long long)i * p > n) break; comp[i * p] = 1; if (i % p == 0) break; }
        }
        cout << primes.size() << endl;
    }
}
', 'g++ 13.3.0 -std=c++17 -O2', 1, 'VERIFIED', UTC_TIMESTAMP(6), 'Executed on 14 tests (3 public examples + 11 hidden) with g++ 13.3.0 -std=c++17 -O2. The stored expected outputs come from this program; the independent Python and C++ references produced identical token output on every test, and every example''s stated output matched. Verified by catalog/build.py.' FROM problems p WHERE p.slug = 'count-primes-up-to-n';

