INSERT INTO reference_solutions (problem_id, language, source_code, runtime_version, solution_version, verification_status, last_verified_at, validation_report)
SELECT p.id, 'python', 'import sys
d = sys.stdin.read().split()
r, c = int(d[0]), int(d[1])
m = [d[2 + i * c:2 + (i + 1) * c] for i in range(r)]
top, bot, left, right = 0, r - 1, 0, c - 1
out = []
while top <= bot and left <= right:
    out += m[top][left:right + 1]
    for i in range(top + 1, bot + 1):
        out.append(m[i][right])
    if top < bot:
        out += m[bot][left:right][::-1]
    if left < right:
        for i in range(bot - 1, top, -1):
            out.append(m[i][left])
    top += 1; bot -= 1; left += 1; right -= 1
print('' ''.join(out))
', 'CPython 3.13.18', 1, 'VERIFIED', UTC_TIMESTAMP(6), 'Executed on 14 tests (4 public examples + 10 hidden) with CPython 3.13.18. The stored expected outputs come from this program; the independent Python and C++ references produced identical token output on every test, and every example''s stated output matched. Verified by catalog/build.py. 2 oversized hidden test(s) were executed in validation but are not stored in the migration (size cap).' FROM problems p WHERE p.slug = 'spiral-matrix-order';
INSERT INTO reference_solutions (problem_id, language, source_code, runtime_version, solution_version, verification_status, last_verified_at, validation_report)
SELECT p.id, 'cpp', '#include <bits/stdc++.h>
using namespace std;
int main() {
    int r, c; cin >> r >> c;
    vector<vector<string>> m(r, vector<string>(c));
    for (auto &row : m) for (auto &x : row) cin >> x;
    vector<vector<char>> seen(r, vector<char>(c, 0));
    int dx[4] = {0, 1, 0, -1}, dy[4] = {1, 0, -1, 0}, x = 0, y = 0, dir = 0;
    for (int k = 0; k < r * c; k++) {                  // walk, turning right whenever the next cell is outside or already used
        cout << m[x][y] << (k + 1 < r * c ? '' '' : ''\\n'');
        seen[x][y] = 1;
        int nx = x + dx[dir], ny = y + dy[dir];
        if (nx < 0 || nx >= r || ny < 0 || ny >= c || seen[nx][ny]) { dir = (dir + 1) % 4; nx = x + dx[dir]; ny = y + dy[dir]; }
        x = nx; y = ny;
    }
}
', 'g++ 13.3.0 -std=c++17 -O2', 1, 'VERIFIED', UTC_TIMESTAMP(6), 'Executed on 14 tests (4 public examples + 10 hidden) with g++ 13.3.0 -std=c++17 -O2. The stored expected outputs come from this program; the independent Python and C++ references produced identical token output on every test, and every example''s stated output matched. Verified by catalog/build.py. 2 oversized hidden test(s) were executed in validation but are not stored in the migration (size cap).' FROM problems p WHERE p.slug = 'spiral-matrix-order';

